script:
/*
* Custom Script for Purchase Receipt
* Adds a "Create Nutrient Batch" button to the form.
*/
frappe.ui.form.on('Purchase Receipt', {
    /**
     * REFRESH: This event runs every time the form is drawn.
     */
    refresh: function(frm) {
        // --- Add the "Create Nutrient Batch" button ---

        // Only show the button for submitted documents that have items.
        if (frm.doc.docstatus === 1 && frm.doc.items && frm.doc.items.length > 0) {

            // This adds the button to the "Create" menu in the top-right of the form.
            frm.add_custom_button(__('Create Nutrient Batch'), function() {
                // When clicked, call our helper function to start the process.
                create_nutrient_batches_from_receipt(frm);
            }, __('Create')); // The last argument specifies the button group
        }
    }
});

/**
 * This is the helper function that contains the main logic.
 */
function create_nutrient_batches_from_receipt(frm) {
    // This function will handle creating one or more Nutrient Batch documents.
    // We will use a dedicated Client Script on the Nutrient Batch side to handle
    // the pre-filling, which is a cleaner approach.

    // 1. Prepare the data to be passed.
    // We create an array of objects, one for each item row in the Purchase Receipt.
    let items_to_process = frm.doc.items.map(function(item_row) {
        return {
            item: item_row.item_code,
            quantity_received: item_row.qty,
            uom: item_row.uom,
            warehouse: item_row.warehouse,
            // Also pass context from the parent document
            company: frm.doc.company,
            supplier: frm.doc.supplier
        };
    });

    // 2. Save this data to local storage. This is the most reliable way to
    //    pass a list of data to a new document form.
    localStorage.setItem('new_nutrient_batch_data', JSON.stringify(items_to_process));

    // 3. Open the form for a new Nutrient Batch.
    frappe.new_doc('Nutrient Batch');
}
